mapper.update:
MERGE INTO DIS_POI_TAB DPT USING ( SELECT #{tabNum,jdbcType=VARCHAR} TAB_NUM, #{tabName,jdbcType=VARCHAR} TAB_NAME, #{tempPath,jdbcType=VARCHAR} TEMP_PATH, #{tempName,jdbcType=VARCHAR} TEMP_NAME, #{tempPrams,jdbcType=VARCHAR} TEMP_PRAMS, #{status,jdbcType=VARCHAR} STATUS, #{createUser,jdbcType=VARCHAR} CREATE_USER, #{createDept,jdbcType=VARCHAR} CREATE_DEPT, #{createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{updateUser,jdbcType=VARCHAR} UPDATE_USER, #{updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM DUAL
) TEMP
ON( DPT.TAB_NUM = TEMP.TAB_NUM )
WHEN MATCHED THEN UPDATE SET DPT.TAB_NAME=TEMP.TAB_NAME, DPT.TEMP_PATH=TEMP.TEMP_PATH, DPT.TEMP_NAME=TEMP.TEMP_NAME, DPT.TEMP_PRAMS=TEMP.TEMP_PRAMS, DPT.STATUS=TEMP.STATUS, DPT.CREATE_USER=TEMP.CREATE_USER, DPT.CREATE_DEPT=TEMP.CREATE_DEPT, DPT.CREATE_TIME=TEMP.CREATE_TIME, DPT.UPDATE_USER=TEMP.UPDATE_USER, DPT.UPDATE_TIME=TEMP.UPDATE_TIME
WHEN NOT MATCHED THEN INSERT ( TAB_NUM, TAB_NAME, TEMP_PATH, TEMP_NAME, TEMP_PRAMS, STATUS, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME
) VALUES ( TEMP.TAB_NUM, TEMP.TAB_NAME, TEMP.TEMP_PATH, TEMP.TEMP_NAME, TEMP.TEMP_PRAMS, TEMP.STATUS, TEMP.CREATE_USER, TEMP.CREATE_DEPT, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME )
